const e={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Blocos de configuração e macros do Klipper prontos para colar - sequências de início, manuseio de filamento, input shaping, bed mesh e mais. Copie um e adicione ao seu printer.cfg (o Editor de Configuração é um bom lugar para colar)."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Ajuda"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Sobre os Modelos de Configuração"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Fechar"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Como usar"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Filtre por categoria para encontrar uma macro ou bloco de configuração."}},{t:0,b:{t:2,i:[{t:3}],s:"Leia a descrição e quais seções ela precisa."}},{t:0,b:{t:2,i:[{t:3}],s:"Copie o modelo, cole na sua configuração e ajuste os valores."}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:"O que são"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Um conjunto selecionado de blocos comuns do Klipper: gcode_macros (PRINT_START, PAUSE/RESUME, carga/descarga de filamento, M600) e seções de configuração ([input_shaper], [bed_mesh], [firmware_retraction], …). São pontos de partida - leia cada um e ajuste para a sua máquina."}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:"Inserindo um modelo"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Copie um modelo e cole no seu printer.cfg - a visualização Raw do Editor de Configuração é um lugar conveniente. Depois de salvar, um reinício do firmware aplica as alterações. Sempre revise os valores primeiro; os padrões aqui são sensatos, mas não estão ajustados à sua impressora."}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:"Seções necessárias"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Cada modelo lista as seções de configuração que define ou das quais depende. Se uma seção já existe na sua configuração, mescle as chaves em vez de colar uma duplicata (uma seção duplicada é rejeitada na inicialização)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Glossário"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:"Modelo"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Um trecho pronto para colar de configuração do Klipper ou G-code de macro que você copia para o printer.cfg."}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:"gcode_macro"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Um comando nomeado que você define na configuração (ex.: PRINT_START) que executa uma sequência de G-code."}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:"Seção"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Um bloco de configuração entre [colchetes], ex.: [bed_mesh] - a unidade em que a configuração do Klipper é agrupada."}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:"Categoria"}},all:{t:0,b:{t:2,i:[{t:3}],s:"Todas as categorias"}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:"Copiar"}},copied:{t:0,b:{t:2,i:[{t:3}],s:"Copiado!"}},requires:{t:0,b:{t:2,i:[{t:3,v:"Seções: "},{t:4,k:"sections"}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:"-"}}},count:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" modelos"}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Carregando modelos…"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Não foi possível carregar os modelos."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Nenhum modelo nesta categoria."}},retry:{t:0,b:{t:2,i:[{t:3}],s:"Tentar novamente"}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:"Blocos de configuração"}},macros:{t:0,b:{t:2,i:[{t:3}],s:"Macros"}}}}};export{e as default};
